import{_ as s,C as n,o as e,c as u,j as i,E as t,a as r,a3 as o}from"./chunks/framework.C6R8kWFE.js";const D=JSON.parse(`{"title":"3-dars (Mentor). BI tizimlari turlari, mutaxassislik rollari va Excel analitik platformasi","description":"","frontmatter":{"title":"3-dars (Mentor). BI tizimlari turlari, mutaxassislik rollari va Excel analitik platformasi","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (BI)","link":"/mentor/9-sinf-bi/"},"week":{"n":1,"link":"/mentor/9-sinf-bi/hafta-01/"},"g":3,"title":"BI tizimlari turlari, mutaxassislik rollari va Excel analitik platformasi","lead":"Katta biznes qanday boshqariladi: BI tizimlarining turlari, jamoaviy rollar va barcha tahlillar poydevori bo'lgan Microsoft Excel bilan yaqindan tanishing.","slide":"/slaydlar/9-sinf-bi/hafta-01/dars-3.html","test":"/slaydlar/9-sinf-bi/hafta-01/dars-3-test.html","student_link":"/9-sinf-bi/hafta-01/dars-3","tabs":[{"g":1,"link":"/mentor/9-sinf-bi/hafta-01/dars-1","current":false},{"g":2,"link":"/mentor/9-sinf-bi/hafta-01/dars-2","current":false},{"g":3,"link":"/mentor/9-sinf-bi/hafta-01/dars-3","current":true}],"prev":{"g":2,"title":"Business Intelligence (BI) asoslari: Katta to'rtlik va hayotiy sikl","link":"/mentor/9-sinf-bi/hafta-01/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/9-sinf-bi/hafta-01/dars-3.md","filePath":"mentor/9-sinf-bi/hafta-01/dars-3.md"}`),d={name:"mentor/9-sinf-bi/hafta-01/dars-3.md"},m={class:"blk"},h={id:"dars-rejasi",tabindex:"-1"},g={class:"blk"},k={id:"mentor-konspekti",tabindex:"-1"},b={class:"blk"},c={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},q={class:"blk"},y={id:"tezkor-nazorat-savollari",tabindex:"-1"},v={class:"blk"},f={id:"uyga-vazifa",tabindex:"-1"};function z(p,a,x,I,_,B){const l=n("Icon");return e(),u("div",null,[i("div",m,[i("h2",h,[t(l,{name:"file-text"}),a[0]||(a[0]=r(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=o("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga BI tizimlarining to&#39;rt asosiy turi (Operatsional, Strategik, Self-Service, Integratsiyalashgan), BI jamoasidagi asosiy mutaxassislik rollari (Data Analyst, Data Engineer, BI Developer, Business User) hamda ma&#39;lumotlar tahlilining fundamental platformasi sifatida Microsoft Excel muhitining o&#39;rni va asosiy tuzilishini tushuntirish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar BI tizimi turlarini maqsadiga qarab farqlay oladi; sohadagi rollarning vazifalarini biladi; Excel dasturining ishchi tuzilishi (Workbook, Worksheet, Row, Column, Cell) va asosiy ma&#39;lumot turlarini amalda to&#39;g&#39;ri qo&#39;llay oladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>O&#39;tgan mavzuni takrorlash (Katta to&#39;rtlik va ETL): 10 daqiqa</li><li>Yangi mavzu: BI tizimlari turlari va rollar: 20 daqiqa</li><li>Excel fundamental analitik vosita sifatida: 25 daqiqa</li><li>Amaliy mashg&#39;ulot (Excelda ma&#39;lumotlar kiritish va formatlash): 15 daqiqa</li><li>Tezkor nazorat va hafta sarhisobi: 10 daqiqa</li></ul></li></ul><hr>",2))]),i("div",g,[i("h2",k,[t(l,{name:"file-text"}),a[3]||(a[3]=r(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=o('<h3 id="_1-bi-tizimlarining-to-rt-asosiy-turi" tabindex="-1">1. BI tizimlarining to&#39;rt asosiy turi <a class="header-anchor" href="#_1-bi-tizimlarining-to-rt-asosiy-turi" aria-label="Permalink to &quot;1. BI tizimlarining to&#39;rt asosiy turi&quot;">​</a></h3><p>Tashkilotlarning maqsadlari va qaror qabul qilish tezligiga qarab BI tizimlari 4 turga bo&#39;linadi:</p><ol><li><strong>Operatsional BI (Operational BI):</strong><ul><li>Kundalik jarayonlar ustidan tezkor nazorat o&#39;rnatish uchun xizmat qiladi.</li><li>Real vaqt yoki yaqin real vaqt rejimidagi ma&#39;lumotlarga tayanadi.</li><li>Misollar: Call-markaz monitoringi, ombordagi qoldiqlar, kunlik savdo kassa paneli.</li></ul></li><li><strong>Strategik BI (Strategic BI):</strong><ul><li>Yuqori boshqaruv bo&#39;g&#39;ini uchun uzoq muddatli maqsadlarni belgilashga xizmat qiladi.</li><li>Yillik va choraklik rejalashtirish, asosiy KPI ko&#39;rsatkichlari, moliyaviy samaradorlik tahlili.</li></ul></li><li><strong>Self-Service BI (Mustaqil tahlil):</strong><ul><li>Dasturchi bo&#39;lmagan xodimlarga (marketing mutaxassislari, savdo menejerlari, HR) mustaqil hisobot va grafiklar yaratish imkonini beradi.</li><li>IT bo&#39;limiga bo&#39;lgan qaramlikni kamaytiradi. Vositalar: Power BI Desktop, Tableau.</li></ul></li><li><strong>Integratsiyalashgan BI (Embedded BI):</strong><ul><li>Analitika alohida dasturda emas, balki xodim ishlayotgan korporativ tizim (CRM, ERP yoki mobil ilova) ichiga bevosita joylashtiriladi.</li></ul></li></ol><h3 id="_2-bi-tizimidagi-mutaxassislik-rollari" tabindex="-1">2. BI tizimidagi mutaxassislik rollari <a class="header-anchor" href="#_2-bi-tizimidagi-mutaxassislik-rollari" aria-label="Permalink to &quot;2. BI tizimidagi mutaxassislik rollari&quot;">​</a></h3><p>BI loyihasida muvaffaqiyatga erishish uchun bir nechta mutaxassislar hamkorlikda ishlaydi:</p><ul><li><strong>Ma’lumotlar muhandisi (Data Engineer):</strong> Infratuzilma &quot;poydevori&quot;. Ma&#39;lumot quvurlarini (ETL/ELT) quradi, Data Warehouse va Data Lake tizimlarini boshqaradi.</li><li><strong>Ma’lumotlar tahlilchisi (Data Analyst):</strong> BI ning &quot;ko&#39;zlari va miyasi&quot;. Ma&#39;lumotlarni tahlil qiladi, qonuniyatlarni topadi, hisobotlar va dashboardlar yaratadi.</li><li><strong>BI Dasturchi (BI Developer):</strong> Dashboardlarni texnik ishlab chiquvchi, semantik model (DAX, SQL) va interfeysni loyihalashtiruvchi mutaxassis.</li><li><strong>Biznes foydalanuvchisi / Rahbar (Business User / Executive):</strong> Natijalarni ko&#39;rib, strategik va operatsion qarorlarni qabul qiluvchi shaxs.</li></ul><h3 id="_3-excel-—-ma-lumotlar-bilan-ishlashning-fundamental-vositasi" tabindex="-1">3. Excel — Ma&#39;lumotlar bilan ishlashning fundamental vositasi <a class="header-anchor" href="#_3-excel-—-ma-lumotlar-bilan-ishlashning-fundamental-vositasi" aria-label="Permalink to &quot;3. Excel — Ma&#39;lumotlar bilan ishlashning fundamental vositasi&quot;">​</a></h3><p>Ko&#39;plab tahlilchilar o&#39;z faoliyatini aynan Excel orqali boshlaydi. Nega?</p><ul><li><strong>Analitik fikrlashni shakllantiradi:</strong> Jadval, qator, ustun va kataklar orqali mantiqiy tuzilmani tushunishni o&#39;rgatadi.</li><li><strong>Ishchi tuzilma:</strong><ul><li><em>Workbook (Ishchi kitob):</em> Butun fayl (<code>.xlsx</code>).</li><li><em>Worksheet (Ishchi varaq):</em> Kitob ichidagi alohida varaqlar.</li><li><em>Row (Qator):</em> Raqamlar bilan belgilanadi (1, 2, 3...).</li><li><em>Column (Ustun):</em> Lotin harflari bilan belgilanadi (A, B, C...).</li><li><em>Cell (Katak):</em> Ustun va qator kesishmasi (masalan, <code>B4</code>, <code>D12</code>).</li></ul></li><li><strong>Ma&#39;lumot turlari (Data Types):</strong><ul><li>Matn (Text): So&#39;zlar, ismlar, toifalar.</li><li>Son (Number): Butun va o&#39;nlik sonlar.</li><li>Valyuta (Currency): Pul birliklari ($ yoki so&#39;m).</li><li>Sana/Vaqt (Date/Time): Kalendar sanalari.</li><li>Foiz (Percentage): Ulushlar va o&#39;sish sur&#39;atlari.</li></ul></li></ul><hr>',10))]),i("div",b,[i("h2",c,[t(l,{name:"file-text"}),a[6]||(a[6]=r(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=o('<h3 id="_1-topshiriq-bi-turlarini-vaziyatga-moslashtirish-oson" tabindex="-1">1-topshiriq. BI turlarini vaziyatga moslashtirish (oson) <a class="header-anchor" href="#_1-topshiriq-bi-turlarini-vaziyatga-moslashtirish-oson" aria-label="Permalink to &quot;1-topshiriq. BI turlarini vaziyatga moslashtirish (oson)&quot;">​</a></h3><p>Quyidagi vaziyatlarga mos BI turini (Operatsional, Strategik, Self-Service, Embedded) tanlang:</p><ol><li>Ombor mudiri har soatda omborda nechta quti mahsulot qolganini ko&#39;rib turadi.</li><li>Kompaniya bosh direktori kelasi 3 yillik investitsiya rejasini tuzish uchun bozor ulushini tahlil qilmoqda.</li><li>Marketing xodimi Power BI orqali IT dasturchilarga murojaat qilmasdan yangi reklama hisobotini mustaqil tuzdi.</li><li>Xodim CRM dasturidan chiqmasdan mijoz kartochkasi ichida uning xarid grafigini ko&#39;rmoqda.</li></ol><p><strong>Yechim:</strong></p><ol><li>Operatsional BI (chunki real vaqt monitoringi).</li><li>Strategik BI (chunki uzoq muddatli yillik strategiya).</li><li>Self-Service BI (chunki IT xodimisiz mustaqil hisobot yaratildi).</li><li>Integratsiyalashgan (Embedded) BI (chunki boshqa dastur interfeysi ichiga o&#39;rnatilgan).</li></ol><h3 id="_2-topshiriq-kasbiy-rollar-mas-uliyati-o-rta" tabindex="-1">2-topshiriq. Kasbiy rollar mas&#39;uliyati (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-kasbiy-rollar-mas-uliyati-o-rta" aria-label="Permalink to &quot;2-topshiriq. Kasbiy rollar mas&#39;uliyati (o&#39;rta)&quot;">​</a></h3><p>Kompaniyada yangi savdo dashboardi yaratilmoqda. Quyidagi vazifalarni mos mutaxassisga (Data Engineer, Data Analyst, BI Developer, Business User) biriktiring:</p><ul><li>A: PostgreSQL bazasidagi ma&#39;lumotlarni har kecha tozalab, Data Warehouse&#39;ga yuklovchi avtomatik skript yozish.</li><li>B: Savdo natijalarini o&#39;rganib, nima sababdan Andijon filialida sotuvlar tushib ketganini tahlil qilish va xulosa chiqarish.</li><li>C: Power BI Desktop&#39;da murakkab DAX o&#39;lchovlari bilan interaktiv dashboard dizaynini texnik kodlash.</li><li>D: Tayyor dashboarddagi ko&#39;rsatkichlarga qarab, Andijon filialiga yangi menejer tayinlash to&#39;g&#39;risida buyruq chiqarish.</li></ul><p><strong>Yechim:</strong></p><ul><li>A — Data Engineer (ma&#39;lumot infratuzilmasi va ETL quvuri).</li><li>B — Data Analyst (tahlil va sabab-oqibat xulosalari).</li><li>C — BI Developer (dashboardni texnik ishlab chiqish).</li><li>D — Business User / Rahbar (boshqaruv qarorini qabul qilish).</li></ul><h3 id="_3-topshiriq-excelda-ma-lumotlar-strukturasini-loyihalash-qiyin" tabindex="-1">3-topshiriq. Excelda ma&#39;lumotlar strukturasini loyihalash (qiyin) <a class="header-anchor" href="#_3-topshiriq-excelda-ma-lumotlar-strukturasini-loyihalash-qiyin" aria-label="Permalink to &quot;3-topshiriq. Excelda ma&#39;lumotlar strukturasini loyihalash (qiyin)&quot;">​</a></h3><p>Maktab o&#39;quv markazi uchun &quot;Kurslar va to&#39;lovlar&quot; hisobotini tayyorlash kerak.</p><ol><li>Excelda qanday ustunlar bo&#39;lishi kerak?</li><li>Har bir ustun uchun qaysi ma&#39;lumot turi (Text, Number, Date, Currency) to&#39;g&#39;ri keladi?</li><li>Bitta namunaviy qator yozib ko&#39;rsating.</li></ol><p><strong>Yechim:</strong></p><ol><li>Kerakli ustunlar: <code>O&#39;quvchi ID</code>, <code>F.I.Sh.</code>, <code>Kurs nomi</code>, <code>To&#39;lov sanasi</code>, <code>To&#39;lov summasi</code>, <code>Chegirma foizi</code>.</li><li>Ma&#39;lumot turlari: <ul><li><code>O&#39;quvchi ID</code>: Text (chunki raqam sifatida hisob-kitob qilinmaydi, masalan <code>ST-104</code>).</li><li><code>F.I.Sh.</code>: Text.</li><li><code>Kurs nomi</code>: Text.</li><li><code>To&#39;lov sanasi</code>: Date (masalan <code>2026-10-04</code>).</li><li><code>To&#39;lov summasi</code>: Currency (masalan <code>450 000 so&#39;m</code>).</li><li><code>Chegirma foizi</code>: Percentage (masalan <code>10%</code>).</li></ul></li><li>Namunaviy yozuv: <code>[&quot;ST-101&quot;, &quot;Alisher Navoiy&quot;, &quot;Python Asoslari&quot;, &quot;2026-10-01&quot;, 500000, 0.10]</code>.</li></ol><hr>',16))]),i("div",q,[i("h2",y,[t(l,{name:"file-text"}),a[9]||(a[9]=r(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=o("<ol><li>Nima uchun Self-Service BI korxonalarda katta inqilob yaratdi? <ul><li><em>Javob:</em> Chunki oddiy menejerlar IT mutaxassislarining navbatini kutmasdan, kerakli hisobotlarni o&#39;zlari mustaqil yarata oladigan bo&#39;ldi.</li></ul></li><li>Data Engineer va Data Analyst rollari o&#39;rtasidagi asosiy farq nima? <ul><li><em>Javob:</em> Data Engineer ma&#39;lumotlarni yig&#39;ish va saqlash infratuzilmasini quradi, Data Analyst esa tayyor ma&#39;lumotlardan biznes uchun tushuncha (insight) chiqaradi.</li></ul></li><li>Excel katakchasi (Cell) qanday nomlanadi? <ul><li><em>Javob:</em> Ustun harfi va qator raqami birikmasi bilan (masalan: <code>A1</code>, <code>C15</code>).</li></ul></li></ol><hr>",2))]),i("div",v,[i("h2",f,[t(l,{name:"house"}),a[12]||(a[12]=r(" Uyga vazifa ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[14]||(a[14]=i("p",null,"Kompyuteringizda Microsoft Excel (yoki Google Sheets) dasturini oching. O'zingizning oilaviy haftalik xarajatlaringiz bo'yicha 5 ta qatordan iborat jadval tuzing. Jadvalda matn, sana, raqam va valyuta formatlaridan to'g'ri foydalaning.",-1))])])}const S=s(d,[["render",z]]);export{D as __pageData,S as default};
